import pytest
from unittest.mock import patch, MagicMock

class TestProviderUtils:
    def test_get_provider_from_model_extracts_prefix(self):
        from core.interpreter_bridge import _get_provider_from_model
        assert _get_provider_from_model("ollama_chat/gemma4:e4b") == "ollama_chat"
        assert _get_provider_from_model("zai/glm-4") == "zai"
        assert _get_provider_from_model("cerebras/qwen3") == "cerebras"

