        from core.interpreter_bridge import _get_provider_from_model
        assert _get_provider_from_model("unknown_model") == "unknown"

    def test_is_provider_rate_limited_false_when_not_tracked(self):
        from core.interpreter_bridge import _is_provider_rate_limited, _RATE_LIMIT_TRACKER
