        _RATE_LIMIT_TRACKER["groq"] = 950.0  # 50s ago < 120s cooldown
        assert _is_provider_rate_limited("groq") is True

    def test_mark_provider_rate_limited_updates_tracker(self):
        from core.interpreter_bridge import mark_provider_rate_limited, _RATE_LIMIT_TRACKER
        _RATE_LIMIT_TRACKER.clear()
        mark_provider_rate_limited("groq/moonshotai")
        assert "groq" in _RATE_LIMIT_TRACKER


