class TestChunkOutput:
    def test_chunk_output_empty(self):
        from core.interpreter_bridge import chunk_output
        assert chunk_output("") == []

    def test_chunk_output_under_limit(self):
        from core.interpreter_bridge import chunk_output
        result = chunk_output("short text", max_length=4000)
        assert result == ["short text"]

