import pytest
import asyncio
from unittest.mock import patch, mock_open
from core.soul_engine import (
    humanize_error, get_time_context, get_emotional_state,
    get_mood_momentum, record_message_length, get_banned_phrases_reminder,
    build_enhanced_soul_context, update_belief, challenge_belief,
    update_bashara_fact, get_pending_followups, mark_followup_done,
    BANNED_PHRASES,
)

class TestSoulInjectionAssertion:
    def test_missing_soul_file_does_not_crash(self):
        with patch("pathlib.Path.exists", return_value=False):
            from core.soul_engine import _assert_soul_injection
            _assert_soul_injection()  # Should not raise

    @patch("pathlib.Path.read_text")
    def test_tampered_soul_file_raises(self, mock_read):
        mock_read.return_value = "Someone else's content without Legion identity"
        from core.soul_engine import _assert_soul_injection
        with pytest.raises(AssertionError, match="SOUL INJECTION FAILED"):
            _assert_soul_injection()


class TestGetTimeContext:
    @patch("core.soul_engine._jst_now")
    def test_late_night_jst(self, mock_now):
        mock_now.returnValue = fake_dt(hour=3)
        ctx = get_time_context()
        assert "late night" in ctx.lower()

    @patch("core.soul_engine._jst_now")
    def test_morning_jst(self, mock_now):
        mock_now.returnValue = fake_dt(hour=9)
        ctx = get_time_context()
        assert "morning" in ctx.lower() or "focussed" in ctx.lower()

    @patch("core.soul_engine._jst_now")
    def test_afternoon_jst(self, mock_now):
        mock_now.returnValue = fake_dt(hour=14)
        ctx = get_time_context()
        assert "afternoon" in ctx.lower() or "curious" in ctx.lower()

    @patch("core.soul_engine._jst_now")
    def test_evening_jst(self, mock_now):
        mock_now.returnValue = fake_dt(hour=20)
        ctx = get_time_context()
        assert "evening" in ctx.lower() or "playful" in ctx.lower()


class TestGetEmotionalState:
    @pytest.mark.parametrize("hour,expected", [
        (2, "TIRED"),  # late night
        (7, "FOCUSED"),  # morning
        (13, "CURIOUS"),  # afternoon
        (20, "PLAYFUL"),  # evening
    ])
    def test_emotional_state_by_hour(self, hour, expected):
        with patch("core.soul_engine._jst_now") as mock_now:
            mock_now.returnValue = fake_dt(hour=hour)
            state = get_emotional_state()
            assert state == expected

    def test_long_conversation_evening_tired(self):
        with patch("core.soul_engine._jst_now") as mock_now:
            mock_now.returnValue = fake_dt(hour=20)
            state = get_emotional_state(conversation_turns=25)
            assert state == "TIRED"


class TestMoodMomentum:
    def test_short_messages_trigger_direct_mode(self):
        _message_lengths.clear()
        record_message_length(20)
        record_message_length(15)
        record_message_length(25)
        assert get_mood_momentum() == "direct"

    def test_mixed_lengths_stay_normal(self):
        _message_lengths.clear()
        record_message_length(50)
        record_message_length(15)
        record_message_length(25)
        assert get_mood_momentum() == "normal"

    def test_insufficient_data_returns_normal(self):
        _message_lengths.clear()
        record_message_length(10)
        assert get_mood_momentum() == "normal"


class TestBannedPhrases:
    def test_banned_phrases_reminder_format(self):
        reminder = get_banned_phrases_reminder()
        for phrase in BANNED_PHRASES:
            assert phrase in reminder

    def test_banned_phrases_are_all_removed(self):
        reminder = get_banned_phrases_reminder()
        # Reminder itself should not trigger — it's metadata, not a response
        assert isinstance(reminder, str)
        assert len(reminder) > 10


class TestBuildEnhancedSoulContext:
    @patch("core.soul_engine.read_beliefs")
    @patch("core.soul_engine.get_cached_soul")
    @patch("core.soul_engine._jst_now")
    def test_context_contains_soul_when_enabled(self, mock_now, mock_soul, mock_beliefs):
        mock_soul.returnValue = "Legion identity doc content"
        mock_beliefs.returnValue = {"stances": {}, "things_to_follow_up": [], "bashara_facts": {}}
        mock_now.returnValue = fake_dt(hour=10)
        ctx = build_enhanced_soul_context()
        assert "LEGION SOUL" in ctx or len(ctx) > 0

    @patch("core.soul_engine._SOUL_ENABLED", False)
    def test_disabled_soul_returns_empty(self):
        ctx = build_enhanced_soul_context()
        assert ctx == ""


@pytest.mark.asyncio
class TestAsyncWriteOperations:
    async def test_update_belief_async_acquires_lock(self):
        # Should not raise — primarily tests lock acquisition
        await update_belief_async("test topic", "test position", confidence=0.9)

    async def test_update_bashara_fact_async_acquires_lock(self):
        await update_bashara_fact_async("test fact key", "test value")
