import pytest
from unittest.mock import patch, MagicMock

class TestInitSwarmLayer:
    @patch("core.swarm.logger")
    def test_import_failure_is_nonfatal(self, mock_logger):
        # When swarms_bot import fails, init_swarm_layer should NOT raise
        with patch("builtins.__import__", side_effect=ImportError("swarms_bot not found")):
            from core.swarm import init_swarm_layer
            init_swarm_layer()  # Must not raise
            mock_logger.warning.assert_called()

    @patch("core.swarm.logger")
    def test_partial_init_failure_is_nonfatal(self, mock_logger):
        # When AuditLogger fails but others succeed        def fake_import(name, *args, **kwargs):
            if "AuditLogger" in name:
                raise RuntimeError("audit down")
            return MagicMock()
        with patch("builtins.__import__", side_effect=fake_import):
            from core.swarm import init_swarm_layer
            init_swarm_layer()
            mock_logger.warning.assert_called()
